from collections import deque

def hops(edges, start, goal):
    nbrs = {}
    for u, v in edges:
        nbrs.setdefault(u, []).append(v)
        nbrs.setdefault(v, []).append(u)
    dist, queue = {start: 0}, deque([start])
    while queue:
        x = queue.popleft()
        if x == goal:
            return dist[x]
        for y in nbrs.get(x, []):
            if y not in dist:
                dist[y] = dist[x] + 1
                queue.append(y)
    return -1

