        } catch (IllegalArgumentException e) {
            return "bad: " + e.getMessage();
        } finally {
            System.out.println("checked " + n);
        }
    }
    public static void main(String[] args) {
        System.out.println(check(5));
        System.out.println(check(-1));
    }
}

public class Main {
